import unittest
from app import summarize
class TestSummary(unittest.TestCase):
    def test_duplicates(self):
        self.assertEqual(summarize([2,2,5])['count'],3)
    def test_empty(self):
        self.assertEqual(summarize([]),{'count':0,'total':0,'mean':None,'min':None,'max':None})

files.app.py:
import json
from pathlib import Path
def settings():
    return json.loads((Path(__file__).parent/'config/settings.json').read_text())

def parse_people(text):
    return [{'name': parts[0], 'age': int(parts[1]), 'active': parts[2]=='yes'}
            for line in text.splitlines()[1:] if line.strip()
            for parts in [line.split(',')]]

